(()=>{'use strict';const A=window.KingdomArt,K=window.KingdomSim,unit=A.unit,building=A.building,icon=A.icon,measure=A.measure;
const aliases={fieldmortar:'howitzer',rifleguard:'prussianguard',combatmedic:'healer',steelworks:'foundry',signalbureau:'university'};
A.icon=k=>icon(k==='steamcrawler'?'howitzer':aliases[k]||k);A.measure=k=>k==='steamcrawler'?{width:100,height:70}:measure(aliases[k]||k);
A.unit=(c,u,t,selected)=>{if(u.kind==='steamcrawler'){c.save();c.translate(u.x,u.y);if(u.facing===-1)c.scale(-1,1);c.fillStyle='#17201b55';c.beginPath();c.ellipse(0,7,46,14,0,0,Math.PI*2);c.fill();if(selected){c.strokeStyle='#ead39d';c.stroke()}for(const x of [-29,-9,12,32]){c.fillStyle='#202a29';c.beginPath();c.arc(x,0,11,0,7);c.fill();c.strokeStyle='#a29c7f';c.lineWidth=3;c.stroke()}c.fillStyle=u.flash>0?'#e8d2a3':'#65736c';c.strokeStyle='#26332c';c.lineWidth=2;c.beginPath();c.moveTo(-44,-8);c.lineTo(-32,-37);c.lineTo(25,-39);c.lineTo(44,-10);c.closePath();c.fill();c.stroke();c.fillStyle='#abb5a5';c.fillRect(-18,-47,43,17);c.fillStyle='#3c4945';c.fillRect(16,-43,39,8);c.fillRect(-34,-59,11,28);c.fillStyle=K.colors[u.team];c.fillRect(-9,-29,17,10);for(let i=0;i<3;i++){c.fillStyle='#b4b8ab'+['44','33','22'][i];c.beginPath();c.arc(-29+Math.sin(t+i)*8,-69-i*13-(t*9%11),8+i*3,0,7);c.fill()}c.restore();return true}if(!aliases[u.kind])return unit(c,u,t,selected);unit(c,{...u,kind:aliases[u.kind]},t,selected);c.save();if(u.kind==='combatmedic'){c.fillStyle='#eadfc3';c.fillRect(u.x+6,u.y-42,14,16);c.fillStyle='#b24b3b';c.fillRect(u.x+11,u.y-40,4,12);c.fillRect(u.x+8,u.y-36,10,4)}if(u.kind==='rifleguard'){c.strokeStyle='#c9bc8c';c.lineWidth=3;c.beginPath();c.moveTo(u.x-13,u.y-40);c.lineTo(u.x+15,u.y-25);c.stroke()}c.restore();return true};
A.building=(c,b,t,selected,ghost)=>{if(!['steelworks','signalbureau'].includes(b.kind))return building(c,b,t,selected,ghost);building(c,{...b,kind:aliases[b.kind]},t,selected,ghost);c.save();if(b.kind==='steelworks'){c.fillStyle='#4d5653';c.fillRect(b.x+45,b.y-145,19,110);c.fillStyle='#9f9b85';c.fillRect(b.x+42,b.y-151,25,8);c.strokeStyle='#c69b56';c.lineWidth=5;c.beginPath();c.arc(b.x-15,b.y-60,15,0,7);c.stroke();for(let i=0;i<4;i++){c.fillStyle='#9caaa338';c.beginPath();c.arc(b.x+55+Math.sin(t+i)*14,b.y-165-i*17-(t*10%17),12+i*4,0,7);c.fill()}}else{c.strokeStyle='#d3bc83';c.lineWidth=3;c.beginPath();c.moveTo(b.x+30,b.y-50);c.lineTo(b.x+30,b.y-165);c.moveTo(b.x+8,b.y-145);c.lineTo(b.x+52,b.y-145);c.moveTo(b.x+12,b.y-128);c.lineTo(b.x+48,b.y-128);c.stroke();c.fillStyle='#e4d6aa';c.fillRect(b.x-35,b.y-45,24,18);c.fillStyle='#614b32';c.font='bold 13px Georgia';c.fillText('ϟ',b.x-23,b.y-31)}c.restore();return true};
})();
